#!/usr/bin/env python3
"""Check observed handshakes against independently generated byte expectations."""
import argparse
from collections import Counter
import csv
import hashlib
import json
from pathlib import Path

FIELDS = {
    "aw": ("awid", "awaddr", "awlen", "awsize", "awburst"),
    "w": ("wdata", "wstrb", "wlast"), "b": ("bid", "bresp"),
    "ar": ("arid", "araddr", "arlen", "arsize", "arburst"),
    "r": ("rid", "rdata", "rresp", "rlast"),
}


def require(ok, reason):
    if not ok:
        raise ValueError(reason)


def wave_samples(path):
    """Read scalar/vector VCD and sample pre-edge bus values (before NBA)."""
    scopes, identifiers, current, updates = [], {}, {}, {}
    header = True

    def edge():
        nxt = current | updates
        rising = current.get("clk") == 0 and nxt.get("clk") == 1 and current.get("reset_n") == 1
        sample = {k: v for k, v in current.items() if k not in ("clk", "reset_n")} if rising else None
        current.update(updates); updates.clear()
        return sample

    with Path(path).open() as f:
        for line in f:
            fields = line.split()
            if not fields:
                continue
            if header:
                if fields[0] == "$scope": scopes.append(fields[2])
                elif fields[0] == "$upscope": scopes.pop()
                elif fields[0] == "$var":
                    name = fields[4]
                    if name in ("clk", "reset_n") or (scopes[-1:] == ["bus"] and name != "aclk"):
                        identifiers[fields[3]] = name
                elif fields[0] == "$enddefinitions": header = False
                continue
            if line.startswith("#"):
                sample = edge()
                if sample is not None: yield sample
            elif line[0] in "01xzXZ":
                code = line.strip()[1:]
                if code in identifiers:
                    updates[identifiers[code]] = int(line[0]) if line[0] in "01" else None
            elif line[0] in "bB" and len(fields) == 2 and fields[1] in identifiers:
                bits = fields[0][1:]
                updates[identifiers[fields[1]]] = None if any(c in bits.lower() for c in "xz") else int(bits, 2)
        sample = edge()
        if sample is not None: yield sample


def check(directory, workload_path, waveform=True):
    directory = Path(directory)
    workload = json.loads(Path(workload_path).read_text())
    sim = json.loads((directory / "simulation.json").read_text())
    writes, reads = workload["writes"], workload["reads"]
    expected_w = [(d, s, int(i==t["beats"]-1)) for t in writes for i, (d, s) in enumerate(zip(t["data"], t["strobes"]))]
    expected_r = [(t["id"], d, t["resp"], int(i==t["beats"]-1)) for t in reads for i, d in enumerate(t["expected"])]
    w_limits = []
    for t in writes: w_limits.append((w_limits[-1] if w_limits else 0)+t["beats"])
    indexes = Counter(); stalls = Counter(); max_pending = Counter()
    aw_cycles, w_first_cycles = [], []
    previous = None
    semantic = hashlib.sha256()
    samples = iter(wave_samples(directory / "axi.vcd")) if waveform else None
    total_cycles, concurrent = 0, 0
    with (directory / "bus.csv").open() as stream:
        for raw in csv.DictReader(stream):
            cycle = int(raw.pop("cycle"))
            require(cycle == total_cycles+1, "trace cycles are not contiguous")
            total_cycles = cycle
            try:
                row = {k: int(v, 16) for k, v in raw.items()}
            except (ValueError, TypeError):
                raise ValueError("unknown/malformed bus signal in trace") from None
            if samples is not None:
                sample = next(samples, None)
                require(sample is not None and all(sample.get(k) == v for k, v in row.items()),
                        f"waveform/trace mismatch at cycle {cycle}")
            for channel, names in FIELDS.items():
                valid, ready = channel+"valid", channel+"ready"
                require(row[valid] in (0,1) and row[ready] in (0,1), "invalid handshake level")
                if previous and previous[valid] and not previous[ready]:
                    require(row[valid] == 1 and all(row[n] == previous[n] for n in names),
                            f"{channel} changed while stalled at cycle {cycle}")
                stalls[channel] += int(row[valid] and not row[ready])
                if not (row[valid] and row[ready]):
                    continue
                index = indexes[channel]
                values = tuple(row[n] for n in names)
                if channel in ("aw", "ar"):
                    ts = writes if channel == "aw" else reads
                    require(index < len(ts), f"extra {channel}")
                    t = ts[index]
                    require(values == (t["id"],t["addr"],t["beats"]-1,t["size"],t["burst"]), f"{channel} stimulus mismatch")
                    if channel == "aw": aw_cycles.append(cycle)
                elif channel == "w":
                    require(index < len(expected_w) and values == expected_w[index], "W data/strobe/last mismatch")
                    if index == 0 or index in w_limits: w_first_cycles.append(cycle)
                elif channel == "b":
                    require(index < indexes["aw"] and indexes["w"] >= w_limits[index], "B before AW or all W beats")
                    require(values == (writes[index]["id"], writes[index]["resp"]), "B ID/response/order mismatch")
                else:
                    require(indexes["r_transactions"] < indexes["ar"], "R before AR")
                    require(index < len(expected_r) and values == expected_r[index], "R data/ID/response/last/order mismatch")
                    indexes["r_transactions"] += row["rlast"]
                indexes[channel] += 1
            # Channel ordering in this loop permits same-edge acceptance; B/R
            # can only complete a request whose address/data were observed.
            for key, value in (("write", indexes["aw"]-indexes["b"]), ("read", indexes["ar"]-indexes["r_transactions"])):
                require(0 <= value <= 8, "outstanding limit or response count violated")
                max_pending[key] = max(max_pending[key], value)
            concurrent += int(indexes["aw"]>indexes["b"] and indexes["ar"]>indexes["r_transactions"])
            previous = row
    require(samples is None or next(samples, None) is None, "waveform has untraced clock samples")
    require(indexes == Counter(aw=len(writes), w=len(expected_w), b=len(writes), ar=len(reads), r=len(expected_r), r_transactions=len(reads)),
            "missing/extra requests or completion responses")
    require(sim["exit_code"] == 0 and sim["writes"] == len(writes) and sim["reads"] == len(reads)
            and sim["cycles"] == total_cycles and sim["width"] == workload["width"], "simulation summary mismatch")
    require(0 < sim["pages"] < 200, "sparse allocation bound violated")
    require(all(stalls[ch] > 0 for ch in FIELDS), "not all five channels exercised backpressure")
    before = sum(w < a for w,a in zip(w_first_cycles, aw_cycles))
    after = sum(w > a for w,a in zip(w_first_cycles, aw_cycles))
    require(before > 0 and after > 0 and concurrent > 0 and min(max_pending.values()) > 1,
            "independent channels/outstanding coverage missing")
    # Canonical per-channel completions intentionally omit timing/inter-channel order.
    semantic.update(json.dumps({"B": [(t["id"], t["resp"]) for t in writes], "R": expected_r}, separators=(",",":")).encode())
    result = {"status": "PASS", "counts": dict(indexes), "stalled_cycles": dict(stalls),
              "max_outstanding": dict(max_pending), "w_before_aw": before, "aw_before_w": after,
              "concurrent_read_write_cycles": concurrent, "cycles": total_cycles, "pages": sim["pages"],
              "completion_sha256": semantic.hexdigest(), "response_counts": dict(Counter(t["resp"] for t in writes+reads)),
              "waveform_checked": waveform, "cases": sorted({t["name"] for t in writes+reads if not t["name"].startswith("random-")})}
    (directory / "axi-check.json").write_text(json.dumps(result, indent=2)+"\n")
    return result


if __name__ == "__main__":
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("directory", type=Path)
    p.add_argument("workload", type=Path)
    p.add_argument("--no-waveform", action="store_true")
    a = p.parse_args()
    try:
        print(json.dumps(check(a.directory, a.workload, not a.no_waveform), sort_keys=True))
    except (ValueError, OSError, KeyError, StopIteration) as error:
        p.exit(1, f"AXI_CHECK_REJECT: {error}\n")
